package com.yeyamo_mobile.api.moderation_trust_service.interfaces.rest;import java.util.List;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.moderation_trust_service.application.ModerationService;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.AuditEntry;import jakarta.validation.constraints.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;
@RestController@RequestMapping("/api/v1/moderation/audit")@Tag(name="Moderation audit")@SecurityRequirement(name="bearerAuth")public class AuditController{private final ModerationService service;public AuditController(ModerationService s){service=s;}@GetMapping public List<AuditEntry>latest(@RequestParam(defaultValue="100")@Min(1)@Max(200)int limit){return service.audits(limit);}}
